package com.bank.course;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Returns whether all onboarding steps can be completed (no circular dependency).
public class OnboardingValidator {

    private static final Logger log = Logger.getLogger(OnboardingValidator.class.getName());

    public boolean canFinish(int numSteps, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numSteps; i++) adj.add(new ArrayList<>());
        int[] inDegree = new int[numSteps];
        for (int[] p : prerequisites) {
            // p[1] must come before p[0]
            adj.get(p[1]).add(p[0]);
            inDegree[p[0]]++;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numSteps; i++) {
            if (inDegree[i] == 0) queue.add(i); // steps with no prerequisites
        }

        int processed = 0;
        while (!queue.isEmpty()) {
            int step = queue.poll();
            processed++;
            for (int next : adj.get(step)) {
                if (--inDegree[next] == 0) queue.add(next);
            }
        }
        boolean ok = processed == numSteps;
        log.info("Steps=" + numSteps + " processed=" + processed
                + " -> canFinish=" + ok);
        return ok;
    }
}
