package com.bank.course;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class OnboardingDemo {

    private static final Logger log = Logger.getLogger(OnboardingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Onboarding Dependency Validation");
        OnboardingValidator validator = new OnboardingValidator();

        // 4 steps, acyclic: 0←1←2←3 style chain + branch
        int[][] ok = {{1, 0}, {2, 1}, {3, 1}};
        validator.canFinish(4, ok);                 // true

        // 2 steps with a cycle: 0↔1
        int[][] cyclic = {{1, 0}, {0, 1}};
        validator.canFinish(2, cyclic);             // false
    }
}
